/****************************************************************************
 * Name: esp32s3_bringup
 *
 * Description:
 *   Perform architecture-specific initialization
 *
 *   CONFIG_BOARD_LATE_INITIALIZE=y :
 *     Called from board_late_initialize().
 *
 *   CONFIG_BOARD_LATE_INITIALIZE=n && CONFIG_BOARDCTL=y :
 *     Called from the NSH library
 *
 ****************************************************************************/

int esp32s3_bringup(void)
{
  int ret = 0;
#if (defined(CONFIG_ESP32S3_I2S0) && !defined(CONFIG_AUDIO_CS4344)) || \
    defined(CONFIG_ESP32S3_I2S1)
  bool i2s_enable_tx;
  bool i2s_enable_rx;
#endif

#if defined(CONFIG_ESP32S3_SPIRAM) && \
    defined(CONFIG_ESP32S3_SPIRAM_BANKSWITCH_ENABLE)
  ret = esp_himem_init();
  if (ret < 0)
    {
      syslog(LOG_ERR, "ERROR: Failed to init HIMEM: %d\n", ret);
    }
#endif

#if defined(CONFIG_ESP32S3_SPI) && defined(CONFIG_SPI_DRIVER)
  #ifdef CONFIG_ESP32S3_SPI2
  ret = board_spidev_initialize(ESP32S3_SPI2);
  if (ret < 0)
    {
      syslog(LOG_ERR, "ERROR: Failed to init spidev 2: %d\n", ret);
    }
  #endif

  #ifdef CONFIG_ESP32S3_SPI3
  ret = board_spidev_initialize(ESP32S3_SPI3);
  if (ret < 0)
    {
      syslog(LOG_ERR, "ERROR: Failed to init spidev 3: %d\n", ret);
    }
  #endif

  #ifdef CONFIG_ESPRESSIF_SPI_BITBANG
  ret = board_spidev_initialize(ESPRESSIF_SPI_BITBANG);
  if (ret < 0)
    {
      syslog(LOG_ERR, "ERROR: Failed to init spidev 3: %d\n", ret);
    }
  #endif /* CONFIG_ESPRESSIF_SPI_BITBANG */
#endif /* CONFIG_ESP32S3_SPI && CONFIG_SPI_DRIVER*/

#if defined(CONFIG_ESP32S3_SPI) && defined(CONFIG_SPI_SLAVE_DRIVER)
  #ifdef CONFIG_ESP32S3_SPI2
  struct spi_slave_ctrlr_s *spislave_dev2;
  spislave_dev2 = esp32s3_spislave_ctrlr_initialize(ESP32S3_SPI2);
  if (!spislave_dev2)
    {
      syslog(LOG_ERR, "ERROR: Failed to init spidev 2: %d\n", ret);
    }
  else
    {
      ret = spi_slave_register(spislave_dev2, ESP32S3_SPI2);
      if (ret < 0)
        {
          syslog(LOG_ERR, "ERROR: Failed to init slave spidev 2: %d\n", ret);
        }
    }
  #endif

  #ifdef CONFIG_ESP32S3_SPI3
  struct spi_slave_ctrlr_s *spislave_dev3;
  spislave_dev3 = esp32s3_spislave_ctrlr_initialize(ESP32S3_SPI3);
  if (!spislave_dev3)
    {
      syslog(LOG_ERR, "ERROR: Failed to init spidev 3: %d\n", ret);
    }
  else
    {
      ret = spi_slave_register(spislave_dev3, ESP32S3_SPI3);
      if (ret < 0)
        {
          syslog(LOG_ERR, "ERROR: Failed to init slave spidev 3: %d\n", ret);
        }
    }
  #endif
#endif

#if defined(CONFIG_ESP32S3_SPI) && defined(CONFIG_RPMSG_PORT_SPI_SLAVE)
  esp32s3_rpmsg_initialize();
#endif

#if defined(CONFIG_ESP32S3_EFUSE)
  ret = esp32s3_efuse_initialize("/dev/efuse");
  if (ret < 0)
    {
      syslog(LOG_ERR, "ERROR: Failed to init EFUSE: %d\n", ret);
    }
#endif

#ifdef CONFIG_FS_PROCFS
  /* Mount the procfs file system */

  ret = nx_mount(NULL, "/proc", "procfs", 0, NULL);
