    }
    s_periph_ref_counts++;
    LEAVE_CRITICAL_SECTION(&periph_spinlock);
    return true;
}

uint32_t periph_rtc_dig_clk8m_get_freq(void)
{
#if !SOC_CLK_RC_FAST_SUPPORT_CALIBRATION
