void periph_rtc_dig_clk8m_disable(void)
{
    ENTER_CRITICAL_SECTION(&periph_spinlock);
    assert(s_periph_ref_counts > 0);
    s_periph_ref_counts--;
    if (s_periph_ref_counts == 0) {
        s_rc_fast_freq = 0;
