        rtc_clk_apll_enable(true);
    }
    LEAVE_CRITICAL_SECTION(&periph_spinlock);
}

void periph_rtc_apll_release(void)
{
    ENTER_CRITICAL_SECTION(&periph_spinlock);
    assert(s_apll_ref_cnt > 0);
    s_apll_ref_cnt--;
    if (s_apll_ref_cnt == 0) {
